\label{Theorem1}

Let $\mu$ be an invariant locally square-integrable random measure on $X$. Then there is a unique positive Radon measure $\sigma_{\mu} \in \mathscr{M}_+(\mathcal{S}^+)$ such that

\begin{align*}

\mathrm{Var}_{\mu}(\mathbb{S} f) = \int_{\mathcal{S}^+} |\widehat{\varphi}_f(\omega)|^2 d\sigma_{\mu}(\omega) 

\end{align*}

for every $K$-invariant function $f \in \mathscr{L}_{c}^{\infty}(X)$.

\label{RemarkSpectralMeasures}

The setup for Theorem \ref{Theorem1} is an instance of a more general framework that we develop in Section \ref{Spectral measures}. In Theorem \ref{TheoremSpectralMeasureForAlgebraGMaps} we show that any linear $G$-equivariant map $\alpha : \mathscr{A}(G) \rightarrow \mathcal{H}$ between a ''sufficiently large'' $*$-algebra $\mathscr{A}(G)$ of integrable functions to a $K$-spherical unitary representation $(\pi, \mathcal{H})$ admits a spectral measure $\sigma_{\alpha} \in \mathscr{M}_+(\mathcal{S}^+)$ in the sense that

\begin{align*}

\lVert\alpha(\varphi)\rVert_{\mathcal{H}}^2 = \int_{\mathcal{S}^+} |\widehat{\varphi}(\omega)|^2 d\sigma_{\alpha}(\omega) 

\end{align*}

for all bi-$K$-invariant $\varphi \in \mathscr{A}(G)$. This general framework allows us to extend the notion of Bartlett spectral measures to random \emph{distributions} on $X$. In the Appendix, we prove that every positive Radon measure $\sigma \in \mathscr{M}_+(\mathcal{S}^+)$ whose spherical transform is a bi-$K$-invariant positive-definite distribution on $G$ can be realized as the Bartlett spectral measure of a Gaussian random distribution on $X$.

\label{Theorem2}

Suppose $G$ is a higher rank connected simple matrix Lie group with finite center and $K < G$ a maximal compact subgroup. Then there is a constant $\delta = \delta(G) \in (0, 1)$ such that for any invariant locally square-integrable random measure $\mu$ on $X = G/K$,  

\begin{align*}

\limsup_{r \rightarrow +\infty} \frac{\mathrm{NV}_{\mu}(r)}{\mathrm{Vol}_X(B_r(x_o))^{2 - \delta}} = 0 \, . 

\end{align*}

Let $\mu$ denote an invariant locally square-integrable random distribution on $X = \mathbb{R}^d, \mathbb{H}^d$. 

\begin{enumerate}
    \item If $X = \mathbb{R}^d$, we say that $\mu$ is heat kernel hyperuniform if 
    \begin{align*}
        \limsup_{t \rightarrow +\infty} t^{d/2} \mathrm{Var}_{\mu}(\mathbb{S} h_t) = 0 \, .
    \end{align*}

    \item If $X = \mathbb{H}^d$, we say that $\mu$ is heat kernel hyperuniform if

    \begin{align*}
        \limsup_{t \rightarrow +\infty} t^{3/2} \ensuremath{\mathrm{e}}^{\frac{(d-1)^2}{2}t} \mathrm{Var}_{\mu}(\mathbb{S} h_t) = 0 \, .
    \end{align*}
\end{enumerate}

\label{DefSphericalTransform}

Let $\varphi \in \mathscr{L}^1(G, K)$. The \emph{spherical transform} of $\varphi$ is the function $\widehat{\varphi} \in C_0(\mathcal{S}^+)$ given by

\begin{align*}

\widehat{\varphi}(\omega) = \int_G \varphi(g) \omega(g^{-1}) dm_G(g) \, . 

\end{align*}

\label{TheoremBochner}

Let $\beta \in C(G)$ be a bi-$K$-invariant positive-definite function. Then there is a unique finite positive Borel measure $\sigma_{\beta}$ on $\mathcal{S}^+$ such that

\begin{align*}

\beta(g) = \int_{\mathcal{S}^+} \omega(g) d\sigma_{\beta}(\omega)  \, . 

\end{align*}

\label{CorollarySpectralMeasuresForMatrixCoefficients}

Let $(\pi, \mathcal{H})$ be a $K$-spherical unitary $G$-representation. Then for every $v, w \in \mathcal{H}^K$ there is a unique complex-valued Borel measure $\sigma_{v, w}$ on $\mathcal{S}^+$ with total variation $|\sigma_{v, w}|(\mathcal{S}^+) \leq \lVertv\rVert\lVertw\rVert$ such that

\begin{align*}

\langle \pi(g)v, w \rangle_{\mathcal{H}} = \int_{\mathcal{S}^+} \omega(g) d\sigma_{v, w}(\omega)

\end{align*}

for all $g \in G$. When $v = w$, the measure $\sigma_v := \sigma_{v, v}$ is in addition a positive measure.

\label{LemmaSphericalLinftyRepresentation}

Let $(\pi, \mathcal{H})$ be a $K$-spherical unitary $G$-representation. Then the map $\widehat{\pi} : \mathscr{L}^{\infty}(\mathcal{S}^+) \rightarrow \mathscr{B}(\mathcal{H}^K)$ given implicitly by

\begin{align*}

\langle \widehat{\pi}(\phi)v, w \rangle_{\mathcal{H}} = \int_{\mathcal{S}^+} \phi(\omega) d\sigma_{v, w}(\omega)

\end{align*}

for all $v, w \in \mathcal{H}^K$ is a well-defined $*$-algebra homomorphism.

If $\beta \in L^1(G, K)$, then we set $\widehat{\pi}(\widehat{\beta}) = \pi(\beta)$. Since the image of $L^1(G, K)$ under the spherical transform is dense in $C_0(\mathcal{S}^+)$ as mentioned in Subsection \ref{The spherical transform}, every $\phi \in \mathscr{L}^{\infty}(\mathcal{S}^+)$ can be approximated pointwise by some sequence $\widehat{\beta}_n \in C_0(\mathcal{S}^+)$ with $\beta_n \in L^1(G, K)$. Since $\sigma_{v, w}$ has finite total variation by Corollary \ref{CorollarySpectralMeasuresForMatrixCoefficients} for every $v, w \in \mathcal{H}^K$, Equation \ref{EqSphericalFormulaForTheL^1(G)MatrixCoefficients} and dominated convergence implies that

\begin{align*}

\langle \widehat{\pi}(\phi)v, w \rangle_{\mathcal{H}} := \lim_{n \rightarrow +\infty} \langle \widehat{\pi}(\widehat{\beta}_n)v, w \rangle_{\mathcal{H}} = \lim_{n \rightarrow +\infty} \int_{\mathcal{S}^+} \widehat{\beta}_n(\omega) d\sigma_{v, w}(\omega) = \int_{\mathcal{S}^+} \phi(\omega) d\sigma_{v, w}(\omega) \, . 

\end{align*}

Moreover, $\mathscr{B}(\mathcal{H}^K)$ is preserved under weak limits, so we see that $\widehat{\pi}(\phi)$ defines a bounded linear operator on $\mathcal{H}^K$. To see that this yields a $*$-representation, note that

\begin{align*}

\widehat{\pi}(\widehat{\beta}_1) \widehat{\pi}(\widehat{\beta}_2)^* = \pi(\beta_1) \pi(\beta_2)^* = \pi(\beta_1 * \beta_2^*) = \widehat{\pi}(\widehat{\beta}_1 \overline{\widehat{\beta}_2})  

\end{align*}

for all $\beta_1, \beta_2 \in L^1(G, K)$, so if $\phi_1, \phi_2 \in \mathscr{L}^{\infty}(\mathcal{S}^+)$ then using the same limiting argument as before yields $\widehat{\pi}(\phi_1)\widehat{\pi}(\phi_2)^* = \widehat{\pi}(\phi_1 \overline{\phi_2})$.

The $\lambda_G$-invariance of $\mathscr{A}(G)$ together with Assumption 1 implies that spherical transforms of functions in $\mathscr{A}(G, K)$ separate points in $\mathcal{S}^+$. To see this, let $\omega_1, \omega_2 \in \mathcal{S}^+$ and suppose $\varphi \in \mathscr{A}(G, K)$ such that $\widehat{\varphi}(\omega_1) = \widehat{\varphi}(\omega_2) \neq 0$. Taking $g \in G$ such that $\omega_1(g) \neq \omega_2(g)$ and considering $(\lambda_G(g)\varphi)^{\natural} \in \mathscr{A}(G, K)$, then a computation utilizing the functional equation in Equation \ref{EqSphericalFunctionFunctionalEquation} yields

\begin{align*}

\widehat{(\lambda_G(g)\varphi)^{\natural}}(\omega_1) = \omega_1(g^{-1}) \widehat{\varphi}(\omega_1) \neq \omega_2(g^{-1}) \widehat{\varphi}(\omega_2) = \widehat{(\lambda_G(g)\varphi)^{\natural}}(\omega_2) \, . 

\end{align*}

\label{TheoremSpectralMeasureForAlgebraGMaps}

There is a unique positive Radon measure $\sigma_{\alpha} \in \mathscr{M}_+(\mathcal{S}^+)$ such that

\begin{align*}

\lVert\alpha(\varphi)\rVert_{\mathcal{H}}^2 = \int_{\mathcal{S}^+} |\widehat{\varphi}(\omega)|^2 d\sigma_{\alpha}(\omega) 

\end{align*}

for all $\varphi \in \mathscr{A}(G, K)$.

\label{RemarkPlancherelMeasure}

If $\mathscr{A}(G) \subset \mathscr{L}^1(G) \cap \mathscr{L}^2(G)$ satsfies Assumption 1 and $\alpha : \mathscr{A}(G) \rightarrow L^2(G)$ is the canonical map, then the \emph{spherical Plancherel measure} $\sigma_{\mathcal{P}} := \sigma_{\alpha}$ defined through Theorem \ref{TheoremSpectralMeasureForAlgebraGMaps} is the unique positive Radon measure on $\mathcal{S}^+$ satisfying

\begin{align*}

\lVert\varphi\rVert_{L^2(G)}^2 = \int_{\mathcal{S}^+} |\widehat{\varphi}(\omega)|^2 d\sigma_{\mathcal{P}}(\omega)  

\end{align*}

for all $\varphi \in \mathscr{A}(G, K)$.

\label{LemmaMutualAbsoluteContinuityOfBochnerMeasures}

Let $\varphi_1, \varphi_2 \in \mathscr{A}(G, K)$. Then for every $\phi \in \mathscr{L}^{\infty}(\mathcal{S}^+)$ we have

\begin{align*}

\int_{\mathcal{S}^+} \phi  |\widehat{\varphi}_1|^2 d\sigma_{\alpha(\varphi_2)} = \int_{\mathcal{S}^+} \phi \, d\sigma_{\alpha(\varphi_1 * \varphi_2)} = \int_{\mathcal{S}^+} \phi  |\widehat{\varphi}_2|^2 d\sigma_{\alpha(\varphi_1)} \, . 

\end{align*}

In particular, $|\widehat{\varphi}_1|^2  \sigma_{\alpha(\varphi_2)} = |\widehat{\varphi}_2|^2  \sigma_{\alpha(\varphi_1)}$ as measures on $\mathcal{S}^+$.

Since $(G, K)$ is Gelfand and $\varphi_1, \varphi_2 \in \mathscr{A}(G, K)$, then $\varphi_1 * \varphi_2 = \varphi_2 * \varphi_1$, so it suffices to prove the first equality in the statement. To do this we use Bochner's Theorem for matrix coefficients in Corollary \ref{CorollarySpectralMeasuresForMatrixCoefficients} and the $\mathscr{L}^{\infty}(\mathcal{S}^+)$-homomorphism $\widehat{\pi}$ from Lemma \ref{LemmaSphericalLinftyRepresentation} to write

\begin{align*}

\int_{\mathcal{S}^+} \phi \, d\sigma_{\alpha(\varphi_1 * \varphi_2)} = \Big\langle \widehat{\pi}(\phi)\alpha(\varphi_1 * \varphi_2), \alpha(\varphi_1 * \varphi_2) \Big\rangle_{\mathcal{H}} \, . 

\end{align*}

From the $L^1(G)$-equivariance of $\alpha$,

\begin{align*}

\alpha(\varphi_1 * \varphi_2) = \alpha(\lambda_G(\varphi_1) \varphi_2) = \pi(\varphi_1)\alpha(\varphi_2) \, , 

\end{align*}

so that

\begin{align*}

\int_{\mathcal{S}^+} \phi \, d\sigma_{\alpha(\varphi_1 * \varphi_2)} &= \Big\langle \widehat{\pi}(\phi)\alpha(\varphi_1 * \varphi_2), \alpha(\varphi_1 * \varphi_2) \Big\rangle_{\mathcal{H}} \\

&= \Big\langle \widehat{\pi}(\phi)\pi(\varphi_1)\alpha(\varphi_2), \pi(\varphi_1)\alpha(\varphi_2) \Big\rangle_{\mathcal{H}} \\

&= \Big\langle \pi(\varphi_1^*) \widehat{\pi}(\phi)\pi(\varphi_1)\alpha(\varphi_2), \alpha(\varphi_2) \Big\rangle_{\mathcal{H}} \, . 

\end{align*}

By definition of the $\mathscr{L}^{\infty}(\mathcal{S}^+)$-homomorphism $\widehat{\pi}$, the operator in the latter inner product can be rewritten using Lemma \ref{LemmaSphericalLinftyRepresentation} as

\begin{align*}

\pi(\varphi_1^*) \widehat{\pi}(\phi)\pi(\varphi_1) = \widehat{\pi}(\overline{\widehat{\varphi}_1}) \widehat{\pi}(\phi) \widehat{\pi}(\widehat{\varphi}_1) = \widehat{\pi}(\phi |\widehat{\varphi}_1|^2) \, . 

\end{align*}

Finally, using Bochner's Theorem for matrix coefficents in Corollary \ref{CorollarySpectralMeasuresForMatrixCoefficients} again, we get that

\begin{align*}

\int_{\mathcal{S}^+} \phi \, d\sigma_{\alpha(\varphi_1 * \varphi_2)} &= \Big\langle \widehat{\pi}(\phi |\widehat{\varphi}_1|^2) \alpha(\varphi_2), \alpha(\varphi_2) \Big\rangle_{\mathcal{H}} = \int_{\mathcal{S}^+} \phi |\widehat{\varphi}_1|^2 d\sigma_{\alpha(\varphi_2)} \, .

\end{align*}

By Assumption 1 in the beginning of Section \ref{Spectral measures}, there is for every $\omega \in \mathcal{S}^+$ a $\varphi_{\omega} \in \mathscr{A}(G, K)$ such that $\widehat{\varphi}_{\omega}(\omega) \neq 0$, so that $|\widehat{\varphi}_{\omega}(\omega)|^2 > 0$. Since $\widehat{\varphi}_{\omega}$ is continuous, there is an open subset $U_{\omega} \subset \mathcal{S}^+$ such that $|\widehat{\varphi}_{\omega}(\omega')|^2 > 0$ for all $\omega' \in U_{\omega}$, which yields an open cover

\begin{align*}

Q \subset \bigcup_{\omega \in Q} U_{\omega} \, . 

\end{align*}

Since $Q$ is compact, there are $\omega_1, \dots , \omega_n \in Q$ such that

\begin{align*}

Q \subset \bigcup_{i = 1}^n U_{\omega_i} \, , 

\end{align*}

so taking $F = |\widehat{\varphi}_{\omega_1}|^2 + \dots + |\widehat{\varphi}_{\omega_n}|^2 \in \mathscr{C}_+(\mathcal{S}^+)$ finishes the proof.

As stated in Equation \ref{EqMainMeasureIdentity} we have that 

\begin{align*}

\int_{\mathcal{S}^+} \phi(\omega) F_1(\omega) d\sigma_{F_2}(\omega) = \int_{\mathcal{S}^+} \phi(\omega) F_2(\omega) d\sigma_{F_1}(\omega)

\end{align*}

for all $\phi \in \mathscr{L}^{\infty}(\mathcal{S}^+)$ and all $F_1, F_2 \in \mathscr{C}_+(\mathcal{S}^+)$. By Lemma \ref{LemmaPositiveSphericalTransformsOnCompactSubsets} we may for each $\phi \in C_c(\mathcal{S}^+)$ take a function $F_{\phi} \in \mathscr{C}_+(\mathcal{S}^+)$ that is strictly positive on the compact support $\mathrm{supp}(\phi) \subset \mathcal{S}^+$ and consider

\begin{align*}

\sigma_{\alpha}(\phi) := \int_{\mathcal{S}^+} \phi(\omega) \frac{d\sigma_{F_{\phi}}(\omega)}{F_{\phi}(\omega)} \, . 

\end{align*}

We claim that $\sigma_{\alpha}$ is a well-defined positive continuous linear functional on $C_c(\mathcal{S}^+)$ with respect to the inductive topology over compact subsets.

First, to see that $\sigma_{\alpha}$ is well-defined, suppose that $F_1, F_2 \in \mathscr{C}_+(\mathcal{S}^+)$ are strictly positive on $\mathrm{supp}(\phi)$. Then $\phi/F_1, \phi/F_2$ and $\phi/(F_1F_2)$ are compactly supported and continuous, so by Equation \ref{EqMainMeasureIdentity},

\begin{align*}

\int_{\mathcal{S}^+} \phi(\omega) \frac{d\sigma_{F_{1}}(\omega)}{F_{1}(\omega)} &= \int_{\mathcal{S}^+} \phi(\omega) \frac{F_2(\omega) d\sigma_{F_{1}}(\omega)}{F_2(\omega)F_{1}(\omega)} \\

&= \int_{\mathcal{S}^+} \phi(\omega) \frac{F_1(\omega) d\sigma_{F_{2}}(\omega)}{F_2(\omega)F_{1}(\omega)} = \int_{\mathcal{S}^+} \phi(\omega) \frac{d\sigma_{F_{2}}(\omega)}{F_{2}(\omega)} \, . 

\end{align*}

To see that $\sigma_{\alpha}$ is linear, let $\phi_1, \phi_2 \in C_c(\mathcal{S}^+)$, $c_1, c_2 \in \mathbb{C}$ and let $F \in \mathscr{C}_+(\mathcal{S}^+)$ be strictly positive on $\mathrm{supp}(\phi_1) \cup \mathrm{supp}(\phi_2) \supset \mathrm{supp}(c_1\phi_1 + c_2\phi_2)$, so that

\begin{align*}

\int_{\mathcal{S}^+} (c_1\phi_1(\omega) + c_2\phi_2(\omega)) \frac{d\sigma_{F}(\omega)}{F(\omega)} = c_1 \int_{\mathcal{S}^+} \phi_1(\omega) \frac{d\sigma_{F}(\omega)}{F(\omega)} + c_2 \int_{\mathcal{S}^+} \phi_2(\omega) \frac{d\sigma_{F}(\omega)}{F(\omega)} \, . 

\end{align*}

For the continuity of $\sigma_{\alpha}$, note that if $Q \subset \mathcal{S}^+$ is compact and $F_Q \in \mathscr{C}_+(\mathcal{S}^+)$ is strictly positive on $Q$, then

\begin{align*}

\Big|\int_{\mathcal{S}^+} \phi(\omega) \frac{d\sigma_{F_Q}(\omega)}{F_Q(\omega)} \Big| \leq \frac{\sigma_{F_Q}(\mathcal{S}^+)}{\min_{\omega \in Q} F_Q(\omega)} \lVert\phi\rVert_{\infty}

\end{align*}

for all $\phi \in C_c(\mathcal{S}^+)$ with $\mathrm{supp}(\phi) \subset Q$.

We conclude that $\sigma_{\alpha}$ is a positive continuous linear functional on $C_c(\mathcal{S}^+)$, and hence a positive Radon measure on $\mathcal{S}^+$ by the Riesz representation Theorem.

Next, we claim that $\sigma_{F} = F \cdot \sigma_{\alpha}$ as measures on $\mathcal{S}^+$ for any $F \in \mathscr{C}_+(\mathcal{S}^+)$. To see this, let $\phi \in C_b(\mathcal{S}^+)$ be a positive bounded and continuous function and $F \in \mathscr{C}_+(\mathcal{S}^+)$. Take an increasing sequence of positive functions $\chi_n \in C_c(\mathcal{S}^+)$ such that the compact support $\mathrm{supp}(\chi_n)$ is contained in the open subset $U_{F} = \{ \omega \in \mathcal{S}^+ : F(\omega) > 0 \}$ and such that $\chi_n \rightarrow 1$ uniformly on $U_{F}$ as $n \rightarrow +\infty$. Then $F$ is strictly positive on the compact support of $F \cdot \chi_n$, so by the monotone convergence Theorem we see that

\begin{align*}

\int_{\mathcal{S}^+} \phi(\omega) d\sigma_{F}(\omega) &=  \int_{U_{F}} \phi(\omega) F(\omega) \frac{d\sigma_{F}(\omega)}{F(\omega)} \\

&= \lim_{n \rightarrow +\infty} \int_{U_{F}} \phi(\omega) F(\omega) \chi_n(\omega) \frac{d\sigma_{F}(\omega)}{F(\omega)} \\

&= \lim_{n \rightarrow +\infty} \int_{U_{F}} \phi(\omega) F(\omega) \chi_n(\omega) d\sigma_{\alpha}(\omega) = \int_{\mathcal{S}^+} \phi(\omega) F(\omega) d\sigma_{\alpha}(\omega) \, , 

\end{align*}

which proves the claim. 

Finally, the conclusion of Theorem \ref{TheoremSpectralMeasureForAlgebraGMaps} now follows by taking $F = |\widehat{\varphi}|^2$ for $\varphi \in \mathscr{A}(G, K)$,

\begin{align*}

\lVert\alpha(\varphi)\rVert_{\mathcal{H}}^2 &= \int_{\mathcal{S}^+} d\sigma_{\alpha(\varphi)}(\omega) = \int_{\mathcal{S}^+} d\sigma_F(\omega) = \int_{\mathcal{S}^+} F(\omega) d\sigma_{\alpha}(\omega) =  \int_{\mathcal{S}^+} |\widehat{\varphi}(\omega)|^2 d\sigma_{\alpha}(\omega) \, . 

\end{align*}

First, if $v \in \mathcal{K}^G$ then

\begin{align*}

\langle \tau(\beta) v, w \rangle_{\mathcal{K}} = \int_G \beta(g) \langle \tau(g) v, w \rangle_{\mathcal{K}} dm_G(g) = \langle v, w \rangle_{\mathcal{K}} 

\end{align*}

for all $w \in \mathcal{K}$, using that the integral of $\beta$ with respect to $m_G$ is $1$, so $v \in \mathcal{K}^{\tau(\beta)}$. 

Conversely, if $v \in \mathcal{K}^{\tau(\beta)}$ then 

\begin{align*}

\int_G \beta(g) \langle \tau(g) v, w \rangle_{\mathcal{K}} dm_G(g) = \langle v, w \rangle_{\mathcal{K}}

\end{align*}

for all $w \in \mathcal{K}$. Letting $w = v$ and taking real parts of both sides yields

\begin{align*}

0 = \int_G \beta(g) (\lVertv\rVert^2 - \mathrm{Re}\langle \tau(g)v, v \rangle_{\mathcal{K}} ) dm_G(g) = \frac{1}{2} \int_G \beta(g) \lVert\tau(g)v - v\rVert_{\mathcal{K}}^2 dm_G(g) \, , 

\end{align*}

so $\tau(g)v = v$ for all $g \in \mathrm{supp}(\beta)$. Since the support $\mathrm{supp}(\beta)$ generates $G$ and $\tau$ is a group homomorphism then $\tau(g)v = v$ for all $g \in G$, so $v \in \mathcal{K}^G$.

\label{LemmaMeanErgodicTheoremForUnitaryRepresentations}

Let $(\tau, \mathcal{K})$ be a unitary $G$-representation. Then, for every $v \in \mathcal{K}$,

\begin{align*}

\lVert\tau(\beta_n)v - \mathrm{Proj}_{G}(v)\rVert_{\mathcal{K}} \underset{n \rightarrow +\infty}{\longrightarrow} 0 \, . 

\end{align*}

First we make use of the mean ergodic Theorem in Lemma \ref{LemmaMeanErgodicTheoremForUnitaryRepresentations} to find that 

\begin{align*}

\lim_{n \rightarrow +\infty} \lVert\pi(\beta_n)\alpha(\varphi)\rVert_{\mathcal{H}}^2 &= \lVert\mathrm{Proj}_G(\alpha(\varphi))\rVert_{\mathcal{H}}^2 = i_{\alpha}^2 \Big| \int_G \varphi(g) dm_G(g) \Big|^2 = i_{\alpha}^2 \, . 

\end{align*}

On the other hand, if $\omega \in \mathcal{S}^+$ is a positive-definite spherical function with associated $K$-spherical irreducible GNS-representation $(\pi_{\omega}, \mathcal{H}_{\omega}, v_{\omega})$, then

\begin{align*}

\widehat{\beta}_n(\omega) = \langle \pi_{\omega}(\beta_n)v_{\omega}, v_{\omega} \rangle_{\mathcal{H}_{\omega}} \underset{n \rightarrow +\infty}{\longrightarrow} \langle \mathrm{Proj}_G(v_{\omega}), v_{\omega} \rangle_{\mathcal{H}_{\omega}} = \begin{cases} 1 &\mbox{ if } \omega = 1 \\ 0 &\mbox{ else }. \end{cases} 

\end{align*}

Thus $\widehat{\beta}_n \rightarrow \chi_{\{1\}}$ pointwise on $\mathcal{S}^+$. Since 

\begin{align*}

|\widehat{\beta}_n(\omega)|^2 \leq \lVertv_{\omega}\rVert_{\mathcal{H}_{\omega}}^2 \Big| \int_G \beta(g) dm_G(g) \Big|^2 = 1

\end{align*}

for every $\omega \in \mathcal{S}^+$ and 

\begin{align*}

\int_{\mathcal{S}^+} |\widehat{\varphi}(\omega)|^2 d\sigma_{\alpha}(\omega) = \lVert\alpha(\varphi)\rVert_{\mathcal{H}}^2 < +\infty

\end{align*}

by Theorem \ref{TheoremSpectralMeasureForAlgebraGMaps} then Theorem \ref{TheoremSpectralMeasureForAlgebraGMaps} and dominated convergence allows us to compute the desired limit as 

\begin{align*}

\lim_{n \rightarrow +\infty} \lVert\pi(\beta_n)\alpha(\varphi)\rVert_{\mathcal{H}}^2 &= \lim_{n \rightarrow +\infty} \lVert\alpha(\lambda_G(\beta_n)\varphi)\rVert_{\mathcal{H}}^2 = \lim_{n \rightarrow +\infty} \lVert\alpha(\beta_n * \varphi)\rVert_{\mathcal{H}}^2 \\

&= \lim_{n \rightarrow +\infty} \int_{\mathcal{S}^+} |\widehat{\beta}_n(\omega)|^2 |\widehat{\varphi}(\omega)|^2 d\sigma_{\alpha}(\omega) \\

&= |\widehat{\varphi}(1)|^2 \sigma_{\alpha}(\{1\}) = \sigma_{\alpha}(\{1\}) \, .

\end{align*}

\label{LemmaUpperAndLowerConvolutionBoundsOnIndicatorFunctions}

Let $V \subset G$ be an open pre-compact symmetric neighbourhood of the identity. Then for every Borel set $\widetilde{D} \subset G$ with $D = \widetilde{D}.o$,

\begin{align*}

(\rho_V * \chi_{\widetilde{D}_V^-})(s(x)) \leq \chi_{D}(x) \leq (\rho_V * \chi_{\widetilde{D}_V^+})(s(x)) 

\end{align*}

for every $x \in X$.

For the first inequality, a change of variables yields

\begin{align*}

(\rho_V * \chi_{\widetilde{D}_V^-})(s(x)) = \int_{\widetilde{D}_V^-} \rho_V(s(x)g^{-1}) dm_G(g) = \int_{s(x)(\widetilde{D}_V^-)^{-1} \cap V} \rho_V(g) dm_G(g) \, . 

\end{align*}

Note that if $s(x)(\widetilde{D}_V^-)^{-1} \cap V \neq \varnothing$ then $s(x) \in V \widetilde{D}_V^- \subset \widetilde{D}$, so that $x \in D$. Since $\rho_V$ integrates to $1$ over $G$, we get that 

\begin{align*}

(\rho_V * \chi_{\widetilde{D}_V^-})(s(x)) = \chi_D(x) \int_{s(x)(\widetilde{D}_V^-)^{-1} \cap V} \rho_V(g) dm_G(g) \leq \chi_D(x) \, . 

\end{align*}

For the second inequality, we similarly write

\begin{align*}

(\rho_V * \chi_{\widetilde{D}_V^+})(s(x)) = \int_{\widetilde{D}_V^+} \rho_V(s(x)g^{-1}) dm_G(g) = \int_{s(x)(\widetilde{D}_V^+)^{-1} \cap V} \rho_V(g) dm_G(g) \, . 

\end{align*}

If $x \in D$, then $s(x) \in \widetilde{D} \subset v \widetilde{D}_V^+$ for every $v \in V$, meaning that $V \subset s(x) (\widetilde{D}_V^+)^{-1}$ and hence

\begin{align*}

\chi_D(x) \leq \int_{s(x)(\widetilde{D}_V^+)^{-1} \cap V} \rho_V(g) dm_G(g) = (\rho_V * \chi_{\widetilde{D}_V^+})(s(x)) \, . 

\end{align*}

\label{CorollaryTriangleInequalityUpperBoundOnL2Discrepancy}

Let $\widetilde{D} \subset G$ be a Borel set with $D = \widetilde{D}.o$. Then

\begin{align*}

\lVert\mathbb{S}_0\chi_D\rVert_{L^2(\mu)} \leq \lVert\mathbb{S}_0(P_K(\rho_V * \chi_{\widetilde{D}_V^-}))\rVert_{L^2(\mu)} + \lVert\mathbb{S}_0(P_K(\rho_V * \chi_{\widetilde{D}_V^+}))\rVert_{L^2(\mu)} + i_{\mu} m_G(\widetilde{D}_V^+ \backslash \widetilde{D}_V^-)  \, . 

\end{align*}

The inequalities in Equation \ref{EqLinearStatisticOfIndicatorUpperAndLowerBounds} can be written in terms of discrepancies as

\begin{align*}

\mathbb{S}_0(P_K(\rho_V * \chi_{\widetilde{D}_V^-})) + i_{\mu}(m_G(\rho_V &* \chi_{\widetilde{D}_V^-}) - m_G(\widetilde{D})) \\

&\leq \mathbb{S}_0\chi_D \\

&\leq \mathbb{S}_0(P_K(\rho_V * \chi_{\widetilde{D}_V^+})) + i_{\mu}(m_G(\rho_V * \chi_{\widetilde{D}_V^+}) - m_G(\widetilde{D})) \, .

\end{align*}

Note that 

\begin{align*}

m_G(\rho_V * \chi_{\widetilde{D}_V^{\pm}}) = m_G(\rho_V) m_G(\widetilde{D}_V^{\pm}) = \begin{cases} m_G(\widetilde{D}) + m_G(\widetilde{D}_V^+\backslash\widetilde{D}) &\mbox{ if } + \\ m_G(\widetilde{D}) - m_G(\widetilde{D}\backslash\widetilde{D}_V^-) &\mbox{ if } - \, ,\end{cases}

\end{align*}

which yields the inequalities

\begin{align*}

\mathbb{S}_0(P_K(\rho_V * \chi_{\widetilde{D}_V^-})) - i_{\mu} m_G(\widetilde{D}\backslash\widetilde{D}_V^-) \leq \mathbb{S}_0\chi_D \leq \mathbb{S}_0(P_K(\rho_V * \chi_{\widetilde{D}_V^+})) + i_{\mu} m_G(\widetilde{D}^+_V\backslash\widetilde{D})\, .

\end{align*}

Using the triangle inequality, we get that 

\begin{align*}

\lVert\mathbb{S}_0 \chi_D\rVert_{L^2(\mu)} \leq \lVert\mathbb{S}_0(P_K(\rho_V * \chi_{\widetilde{D}_V^-}))\rVert_{L^2(\mu)} + \lVert\mathbb{S}_0(P_K(\rho_V * \chi_{\widetilde{D}_V^+}))\rVert_{L^2(\mu)} + i_{\mu} m_G(\widetilde{D}_V^+\backslash\widetilde{D}_V^-)

\end{align*}

as desired.

\label{DefSphericalSpectralGap}

Let $(\pi, \mathcal{H})$ be a $K$-spherical unitary $G$-representation and $\alpha : \mathscr{A}(G) \rightarrow \mathcal{H}$ a linear continuous $G$-map as in Section \ref{Spectral measures}. If $q \in [2, +\infty]$ then the \emph{spherical $L^q$-coefficient} of $\alpha$ is 

\begin{align*}

I_q(\alpha) := \sup\Big\{ \lVert\omega\rVert_{L^q(G)} : \omega \in \mathrm{supp}(\sigma_{\alpha}) \Big\} \in (0, +\infty] \, . 

\end{align*}

If $\mu$ is an invariant locally square-integrable random measure on $X = G/K$, then we write $I_q(\mu) := I_q(\alpha_0)$, where we recall $\alpha_0(\varphi) = \mathbb{S}_0(P_K\varphi) \in L^2_0(\mu)$ for every $\varphi \in \mathscr{L}_{c}^{\infty}(G)$.

\label{RemarkMatrixCoefficientBoundsForHigherRankSimpleLieGroups}

If $G$ is a higher rank connected simple matrix Lie group with finite center and $K < G$ maximal compact then there are explicit quantitative bounds on matrix coefficients of unitary $G$-representations with $K$-finite vectors, found for example in Borel and Wallach's book \cite{BorelWallachBook}. For a proof of the following we refer to \cite[Theorem 4.1]{GorodnikHigherOrderCorrelations}. In the case of $K$-spherical representations, the statement is that there is a constant $\varepsilon = \varepsilon(G) > 0$ such that

\begin{align*}

|\omega(g)| \leq C \ensuremath{\mathrm{e}}^{-\varepsilon d(g.o, o)} \, , \quad \forall \, \omega \in \mathcal{S}^+ \backslash \{1\} \, , 

\end{align*}

where $d$ is the invariant reference metric on $X = G/K$ and $C > 0$ is independent of $\omega \in \mathcal{S}^+ \backslash \{1\}$. In particular, since $X = G/K$ has at most exponential volume growth, meaning that there is a $\delta_X > 0$ such that 

\begin{align*}

\int_G \ensuremath{\mathrm{e}}^{-\delta_X d(g.o, o)} dm_G(g) < +\infty

\end{align*}

then taking $q \geq \delta_X/\varepsilon$ we get that

\begin{align*}

\int_G |\omega(g)|^q dm_G(g) \leq C^q \int_G \ensuremath{\mathrm{e}}^{- \delta_X d(g.o, o)} dm_G(g) < +\infty 

\end{align*}

for all $\omega \in \mathcal{S}^+ \backslash \{1\}$. In particular, $I_q(\alpha) < +\infty$ for \emph{every} choice of $\alpha$ and hence $I_q(\mu) < +\infty$ for every invariant locally square-integrable random measure $\mu$.

\label{LemmaFiniteLqCoefficientImpliesBoundOnConvolutionStatistic}

Let $\mu$ be an invariant locally square-integrable random measure on $X$ with finite spherical $L^q$-coefficient $I_q(\mu) < +\infty$ for some $q \in [2, +\infty)$. Then, for any Borel set $\widetilde{B} \subset G$ and any $\rho \in \mathscr{L}_{c}^{\infty}(G)$,

\begin{align*}

\lVert\mathbb{S}_0(P_K(\rho * \chi_{\widetilde{B}}))\rVert_{L^2(\mu)} \leq m_G(\widetilde{B})^{\frac{q - 1}{q}} I_q(\mu) \lVert\mathbb{S}_0(P_K\rho)\rVert_{L^2(\mu)} \, . 

\end{align*}

By defintion of the diffraction measure $\sigma_{\mu}$ on $\mathcal{S}^+$ we have 

\begin{align*}

\lVert\mathbb{S}_0(P_K(\rho * \chi_{\widetilde{B}}))\rVert_{L^2(\mu)} = \lVert\widehat{\rho} \cdot \widehat{\chi}_{\widetilde{B}}\rVert_{L^2(\sigma_{\mu})} \, . 

\end{align*}

By Hölder's inequality, we can bound the $L^{\infty}(\sigma_{\mu})$-norm of $\widehat{\chi}_{\widetilde{B}}$ by

\begin{align*}

\lVert\widehat{\chi}_{\widetilde{B}}\rVert_{L^{\infty}(\sigma_{\mu})} = \sup_{\omega \in \mathrm{supp}(\sigma_{\mu})} \Big| \int_{\widetilde{B}} \omega(g^{-1}) dm_G(g) \Big| \leq m_G(\widetilde{B})^{\frac{q-1}{q}} I_q(\mu) 

\end{align*}

to get the desired bound,

\begin{align*}

\lVert\mathbb{S}_0(P_K(\widetilde{\rho} * \chi_{\widetilde{B}}))\rVert_{L^2(\mu)} \leq  m_G(\widetilde{B})^{\frac{q-1}{q}} I_q(\mu) \lVert\widehat{\rho}\rVert_{L^2(\sigma_{\mu})} = m_G(\widetilde{B})^{\frac{q - 1}{q}} I_q(\mu) \lVert\mathbb{S}_0(P_K\rho)\rVert_{L^2(\mu)}\, . 

\end{align*}

An unbounded increasing sequence $(\widetilde{D}_t)_{t > 0}$ of Borel subsets in $G$ is \emph{admissible} if there are constants $c, t_o, \varepsilon_o > 0$ such that for every $t > t_o$ and every $0 < \varepsilon < \varepsilon_o$,

\begin{align*}

\mathcal{O}_{\varepsilon}\widetilde{D}_t \mathcal{O}_{\varepsilon} \subset \widetilde{D}_{t + c\varepsilon} \quad \mbox{ and } \quad m_G(\widetilde{D}_{t + \varepsilon}) \leq (1 + c\varepsilon) m_G(\widetilde{D}_t) \, . 

\end{align*}

\label{LemmaVarianceUpperBoundForAdmissibleSequences}

Let $(\widetilde{D}_t)_{t > 0}$ be an admissible sequence of Borel sets in $G$ and set $D_t = \widetilde{D}_t.o \subset X$. Suppose that $\mu$ is an invariant locally square-integrable random measure on $X$ with finite spherical $L^q$-coefficient $I_q(\mu) < +\infty$ for some $q \in [2, +\infty)$. Then there is a constant $C = C(\mu, q) > 0$ such that for sufficiently large $t > 0$ and sufficiently small $\varepsilon > 0$,

\begin{align*}

\lVert\mathbb{S}_0\chi_{D_t}\rVert_{L^2(\mu)} \leq C \Big( \frac{m_G(\widetilde{D}_t)^{\frac{q-1}{q}}}{m_G(\mathcal{O}_{\varepsilon})} + \varepsilon m_G(\widetilde{D}_t) \Big) \, . 

\end{align*}

Let $t > t_o$. By Corollary \ref{CorollaryTriangleInequalityUpperBoundOnL2Discrepancy} and Lemma \ref{LemmaFiniteLqCoefficientImpliesBoundOnConvolutionStatistic} we have that 

\begin{align*}

\lVert\mathbb{S}_0\chi_{D_t}\rVert_{L^2(\mu)} \leq \,\,  &m_G((\widetilde{D}_t)_{\mathcal{O}_{\varepsilon}}^-)^{\frac{q - 1}{q}} I_q(\mu) \lVert\mathbb{S}_0(P_K\rho_{\mathcal{O}_{\varepsilon
}})\rVert_{L^2(\mu)} \\

&+  m_G((\widetilde{D}_t)_{\mathcal{O}_{\varepsilon}}^+)^{\frac{q - 1}{q}} I_q(\mu) \lVert\mathbb{S}_0(P_K\rho_{\mathcal{O}_{\varepsilon}})\rVert_{L^2(\mu)} \\

&+ i_{\mu} m_G((\widetilde{D}_t)_{\mathcal{O}_{\varepsilon}}^+ \backslash (\widetilde{D}_t)_{\mathcal{O}_{\varepsilon}}^-) \, . 

\end{align*}

Using that the sequence $\widetilde{D}_t$ is admissible, we have that

\begin{align*}

&m_G((\widetilde{D}_t)_{\mathcal{O}_{\varepsilon}}^-) \leq m_G(\widetilde{D}_t), \\

&m_G((\widetilde{D}_t)_{\mathcal{O}_{\varepsilon}}^+) \leq m_G(\widetilde{D}_{t + c\varepsilon}) \leq (1 + c^2\varepsilon)m_G(\widetilde{D}_t), \quad \mbox{ and } \\

&m_G((\widetilde{D}_t)_{\mathcal{O}_{\varepsilon}}^+ \backslash (\widetilde{D}_t)_{\mathcal{O}_{\varepsilon}}^-) \leq \Big( (1 + c^2\varepsilon) - \frac{1}{1 + c^2\varepsilon} \Big) m_G(\widetilde{D}_t) \leq c^2(c^2 + 2)\varepsilon m_G(\widetilde{D}_t) \, . 

\end{align*}

Moreover, using that we specified $\rho_{\mathcal{O}_{\varepsilon}} = m_G(\mathcal{O}_{\varepsilon})^{-1} \chi_{\mathcal{O}_{\varepsilon}}$ along with the triangle inequality yields

\begin{align*}

\lVert\mathbb{S}_0(P_K\rho_{\mathcal{O}_{\varepsilon}})\rVert_{L^2(\mu)} \leq \lVert\mathbb{S}(P_K\rho_{\mathcal{O}_{\varepsilon}})\rVert_{L^2(\mu)} + i_{\mu} \leq \frac{\lVert\mathbb{S}(P_K\chi_{\mathcal{O}_{1}})\rVert_{L^2(\mu)}}{m_G(\mathcal{O}_{\varepsilon})} + i_{\mu} \leq 2 \frac{\lVert\mathbb{S}(P_K\chi_{\mathcal{O}_{1}})\rVert_{L^2(\mu)}}{m_G(\mathcal{O}_{\varepsilon})}

\end{align*}

for sufficiently small $\varepsilon > 0$. Gathering all of these estimates we get 

\begin{align*}

\lVert\mathbb{S}_0\chi_{D_t}\rVert_{L^2(\mu)} \leq 2 (2 + c^2\varepsilon) I_q(\mu) \lVert\mathbb{S}(P_K\chi_{\mathcal{O}_{1}})\rVert_{L^2(\mu)} \frac{m_G(\widetilde{D}_t)^{\frac{q-1}{q}}}{m_G(\mathcal{O}_{\varepsilon})} + c^2(c^2 + 2)\varepsilon m_G(\widetilde{D}_t) \, . 

\end{align*}

Taking 

\begin{align*}

C(\mu, q) = \max\Big\{ 2 (c^2 + 2) I_q(\mu) \lVert\mathbb{S}(P_K\chi_{\mathcal{O}_{1}})\rVert_{L^2(\mu)}, c^2(c^2 + 2)\Big\}

\end{align*}

finishes the proof.

\label{LemmaVarianceDenistyOfDPPs}

The function $\kappa_L(g) := |L(x_o, g.x_o)|^2$ is continuous and bi-$K$-invariant on $G$. Moreover, if $f \in \mathscr{L}_{c}^{\infty}(X)$ then the $\mu_L$-variance of the linear statistic $\mathbb{S} f$ can be written as 

\begin{align*}

\mathrm{Var}_{\mu_L}(\mathbb{S} f) = L(x_o, x_o)(\check{\varphi}_f * \overline{\varphi}_f)(e) - \int_G (\check{\varphi}_f * \overline{\varphi}_f)(g) \kappa_L(g) dm_G(g) \, . 

\end{align*}

Since the kernel $L$ is assumed to be continuous it is clear that $\kappa_L$ is continuous. To show that $\kappa_L$ is bi-$K$-invariant, we first note that for every $g_1, g_2 \in G$,

\begin{align*}

L(g_1.x_o, g_2.x_o) = L(g_1.x_o, g_1(g_1^{-1} g_2).x_o) = c(g_1, x_o) \overline{c(g_1, g_1^{-1}g_2.x_o)} L(x_o, g_1^{-1}g_2.x_o) \, . 

\end{align*}

Since $|c(g, x)| = 1$ for every $g \in G$ and every $x \in X$ by assumption, we find that $|L(g_1.x_o, g_2.x_o)|^2 = \kappa_L(g_1^{-1}g_2)$. Thus for every $k_1, k_2 \in K$ and every $g \in G$,

\begin{align*}

\kappa_L(k_1 g k_2) = |L(k_1^{-1}.x_o, gk_2.x_o)|^2 = |L(x_o, g.x_o)|^2 = \kappa_L(g) \, . 

\end{align*}

For the second part we use the definition of the $G$-invariant measure $m_X$ on $X$,

\begin{align*}

m_X(f) = \int_G \varphi_f(g) dm_G(g)

\end{align*}

and Equation \ref{EqVarianceOfEquivariantDPP} together with $|L(g_1.x_o, g_2.x_o)|^2 = \kappa_L(g_1^{-1}g_2)$ to write

\begin{align*}

\mathrm{Var}_{\mu_L}(\mathbb{S} f) &= L(x_o, x_o) \int_G |\varphi_f(g)|^2 dm_G(g) - \int_{G^2} \varphi_f(g_1) \overline{\varphi_f(g_2)} \kappa_L(g_1^{-1}g_2) dm_G^{\otimes 2}(g_1, g_2) \\

&= L(x_o, x_o) \int_G |\varphi_f(g)|^2 dm_G(g) - \int_{G^2} \varphi_f(g_1) \overline{\varphi_f(g_1g_2)} \kappa_L(g_2) dm_G^{\otimes 2}(g_1, g_2) \, . 

\end{align*}

Finally, observing that

\begin{align*}

\int_G \varphi_f(g_1) \overline{\varphi_f(g_1g_2)} dm_G(g_1) = \int_G \check{\varphi}_f(g_1) \overline{\varphi_f(g_1^{-1}g_2)} dm_G(g_1) = (\check{\varphi}_f * \overline{\varphi}_f)(g_2)

\end{align*}

for every $g_2 \in G$ yields the desired formula.

\label{CorollaryDiffractionMeasureofEquivariantKernalDPP}

If the kernel $L : X \times X \rightarrow \mathbb{C}$ satisfies 

\begin{align*}

\int_X |L(x_o, x)|^4 dm_X(x) < + \infty

\end{align*}

then   

\begin{align*}

\mathrm{Var}_{\mu_L}(\mathbb{S} f) = \int_{\mathcal{S}^+} |\widehat{\varphi}_f(\omega)|^2 (L(x_o, x_o) - \widehat{\kappa}_L(\omega)) d\sigma_{\mathcal{P}}(\omega)

\end{align*}

for all $f \in \mathscr{L}_{c}^{\infty}(X)^K$, where $\sigma_{\mathcal{P}}$ is the spherical Plancherel measure for the pair $(G, K)$ from Remark \ref{RemarkPlancherelMeasure}.

\label{LemmaKtildeValuedCocycleFromSection}

The map $\widetilde{\gamma}_s : \widetilde{G} \times X \rightarrow \widetilde{K}$ given by $\widetilde{\gamma}_s(g, x) = \widetilde{s}(\widetilde{g}.x)^{-1}\widetilde{g}\widetilde{s}(x)$ is a well-defined continuous map satisfying the cocycle identity

\begin{align*}

\widetilde{\gamma}_s(\widetilde{g}_1\widetilde{g}_2, x) = \widetilde{\gamma}_s(\widetilde{g}_1, \widetilde{g}_2.x)\widetilde{\gamma}_s(\widetilde{g}_2, x)

\end{align*}

for all $\widetilde{g}_1, \widetilde{g}_2 \in \widetilde{G}$ and all $x \in X$.

Since $\widetilde{s}(\widetilde{g}.x)\widetilde{\gamma}_s(g, x).x_o = \widetilde{g}\widetilde{s}(x).x_o = \widetilde{g}.x$ then $\widetilde{\gamma}_s(g, x) \in \widetilde{K}$ and from this it is clear that $\widetilde{\gamma}_s$ is also continuous by Assumption 2 above. To see that the cocycle identity holds, we simply compute

\begin{align*}

\widetilde{\gamma}_s(\widetilde{g}_1, \widetilde{g}_2.x)\widetilde{\gamma}_s(\widetilde{g}_2, x) &= \widetilde{s}(\widetilde{g}_1\widetilde{g}_2.x)^{-1}\widetilde{g}_1\widetilde{s}(\widetilde{g}_2.x) \widetilde{s}(\widetilde{g}_2.x)^{-1}\widetilde{g}_2\widetilde{s}(x) \\

&= \widetilde{s}(\widetilde{g}_1\widetilde{g}_2.x)^{-1}\widetilde{g}_1\widetilde{g}_2\widetilde{s}(x) = \widetilde{\gamma}_s(\widetilde{g}_1\widetilde{g}_2, x) \, . 

\end{align*}

\label{DefinitionGtildeKernels}

Let $(\pi, \mathcal{H})$, $\xi$ and $v$ be as in Assumption 4. The kernel $L : X \times X \rightarrow \mathbb{C}$ associated to $(\pi, \xi, v)$ is the function

\begin{align*}

L(x_1, x_2) = \langle \pi(\widetilde{s}(x_1))v, \pi(\widetilde{s}(x_2))v \rangle_{\mathcal{H}} \, . 

\end{align*}

Let $L$ be a kernel as in Definition \ref{DefinitionGtildeKernels}. Then, for every $g \in G$ and every $x_1, x_2 \in X$,

\begin{align*}

L(g.x_1, g.x_2) = \overline{\xi(\widetilde{\gamma}_s(b(g), x_1))} \xi(\widetilde{\gamma}_s(b(g), x_2)) L(x_1, x_2) \, . 

\end{align*}

When $d = 1$, $\lambda = 2\pi$ and $n = 0$, the point process $\mu_{2\pi, 0}$ is the \emph{infinite Ginibre ensemble} in $\mathbb{C}$ with kernel 

\begin{align*}

L_{2\pi, 0}(z_1, z_2) = \ensuremath{\mathrm{e}}^{\pi z_1 \overline{z}_2  - \frac{\pi}{2}(|z_1|^2 + |z_2|^2)} \, . 

\end{align*}

For general dimension $d$ and general $n \in \mathbb{Z}_{\geq 0}$ the corresponding determinantal point process $\mu_{2\pi, n}$ in $\mathbb{C}^d$ are \emph{infinite polyanalytic ensembles of pure type} as defined in \cite{AbreuPereiraRomeroTorquato}.

When $d = 1$, $\widehat{\kappa}_{\lambda, n}$ can be calculated explicitly:

\begin{align*}

\widehat{\kappa}_{\lambda, n}(\zeta) &= \int_{\mathbb{C}} \mathcal{L}_n(\tfrac{1}{2} |\lambda| |z|^2)^2 \ensuremath{\mathrm{e}}^{-\frac{1}{2}|\lambda| |z|^2} J_{0}(2\pi |\zeta| |z|) dA(z) \\

&= 2\pi \int_0^{\infty} \mathcal{L}_n(\tfrac{1}{2} |\lambda| s^2)^2 \ensuremath{\mathrm{e}}^{-\frac{1}{2}|\lambda| s^2} J_{0}(2\pi |\zeta| s) s ds \, . 

\end{align*}

From \cite[Equation 7.422(2), p. 812]{GradshteynRyzhik} with $\nu = \sigma = 0, m = n, \alpha = |\lambda|/2, y = 2\pi|\zeta|$, we get

\begin{align*}

\int_0^{\infty} \mathcal{L}_n(\tfrac{1}{2} |\lambda| s^2)^2 \ensuremath{\mathrm{e}}^{-\frac{1}{2}|\lambda| s^2} J_{0}(2\pi |\zeta| s) s ds = \frac{1}{|\lambda|} \mathcal{L}_n(\tfrac{2\pi^2}{|\lambda|} |\zeta|^2)^2 \ensuremath{\mathrm{e}}^{-\frac{2\pi^2}{|\lambda|} |\zeta|^2} \, , 

\end{align*}

so that 

\begin{align*}

\widehat{\kappa}_{\lambda, n}(\zeta) &= \frac{2\pi}{|\lambda|} \mathcal{L}_n(\tfrac{2\pi^2}{|\lambda|} |\zeta|^2)^2 \ensuremath{\mathrm{e}}^{-\frac{2\pi^2}{|\lambda|} |\zeta|^2} \, . 

\end{align*}

The variance of a linear statistic is thus given by 

\begin{align*}

\mathrm{Var}_{\mu_{\lambda, n}}(\mathbb{S} f) = \int_{\mathbb{C}} |\widehat{\varphi}_f(\zeta)|^2 \Big(1 - \frac{2\pi}{|\lambda|} \mathcal{L}_n(\tfrac{2\pi^2}{|\lambda|} |\zeta|^2)^2 \ensuremath{\mathrm{e}}^{-\frac{2\pi^2}{|\lambda|} |\zeta|^2}\Big) dA(\zeta) \, . 

\end{align*}

Note in particular that $\widehat{\kappa}_{\lambda, n}(0) = 2\pi/|\lambda|$, so the infinite polyanalytic ensembles $\mu_{\lambda, n}$ are spectrally hyperuniform if and only if $\lambda = \pm 2\pi$.

In general, the DPPs $\mu_{\lambda, n}$ are (spectrally) hyperuniform whenever $\widehat{\kappa}_{\lambda, n}(1) = 1$, and this quantity coincides with the notion of \emph{formal dimension} of the representation $\pi_{\lambda, n}$ modulo the center $Z = Z(\widetilde{G}) \cong \mathbb{R}$,

\begin{align*}

d_{\pi_{\lambda, n}} &= \int_{\widetilde{G}/Z} |\langle \pi_{\lambda, n}(\widetilde{g})v_{\lambda, n}, v_{\lambda, n} \rangle_{\mathcal{H}}|^2 dm_{\widetilde{G}/Z}(\widetilde{g}Z) \\

&= \int_{\mathbb{C}^d} |\langle \pi_{\lambda, n}(1, z, 0)v_{\lambda, n}, v_{\lambda, n} \rangle_{\mathcal{H}}|^2 dA(z) = \widehat{\kappa}_{\lambda, n}(1) \, . 

\end{align*}

We are particularly interested in the following cases:

\begin{enumerate}
    \item When $G = X = \mathbb{R}^d$ one can consider the nuclear Frech\'et algebra $\mathscr{A}_o(\mathbb{R}^d) = \mathscr{S}(\mathbb{R}^d, \mathbb{R})$ of real-valued Schwartz functions, whose Frech\'et topology is generated by the seminorms

    \begin{align*}

    \lVertf\rVert_{n, m} = \sup_{x \in \mathbb{R}^d} (1 + \lVertx\rVert)^{n} |\partial^{m} f(x)| 

    \end{align*}

    for all $n \in \mathbb{Z}_{\geq 0}$ and all multi-indices $m \in \mathbb{Z}_{\geq 0}^d$. The strong dual $\mathscr{S}'(\mathbb{R}^d, \mathbb{R})$ is the space of real-valued tempered distributions on $\mathbb{R}^d$, in other words distributions of polynomial growth. More generally, there is for every $\delta \in [0, +\infty)$ a \emph{Gelfand-Shilov space} $\mathscr{A}_o(X) = \mathscr{S}_{\delta}(\mathbb{R}^d, \mathbb{R})$ of smooth functions generated by the seminorms

    \begin{align*}

    \lVertf\rVert_{\delta, n, m} = \sup_{x \in \mathbb{R}^d} (1 + \lVertx\rVert)^{n} \ensuremath{\mathrm{e}}^{\delta\lVertx\rVert} |\partial^{m} f(x)| \, , 

    \end{align*}

    and the corresponding strong dual space $\mathscr{S}_{\delta}'(\mathbb{R}^d, \mathbb{R})$ consists of distributions on $\mathbb{R}^d$ whose asymptotic growth are bounded by $(1 + \lVertx\rVert)^n \ensuremath{\mathrm{e}}^{\delta\lVertx\rVert}$ for some $n \geq 0$. For nuclearity of the Schwartz- and Gelfand-Shilov spaces, see \cite[Chapter II, Section 2, p.86]{GelfandShilovGeneralizedFunctionsVolume2} for general definitions and \cite[Chapter IV, Section 3.2, p.178]{GelfandShilovGeneralizedFunctionsVolume3} for a proof with weights $M_p(x) = (1 + \lVertx\rVert^2)^p \ensuremath{\mathrm{e}}^{\delta\lVertx\rVert}$.

    \item Consider real hyperbolic space $\mathbb{H}^d = G_d/K_d$ with $G_d = \mathrm{SO}^{\circ}(1, d)$ (or more generally a semisimple connected Lie group with finite center) and $K_d = \mathrm{SO}(d)$ (in general a maximal compact subgroup). On $G_d$, one can consider the real \emph{Harish-Chandra $L^p$-spaces} $\mathscr{A}_o(G_d) = \mathscr{C}^p(G_d, \mathbb{R})$ for $p \in (0, 2]$ generated by seminorms

    \begin{align*}

    \lVertf\rVert_{p, n, D_l, D_r} = \sup_{g \in G_d} (1 + \ell(g))^{n} \Xi(g)^{-2/p} |(D_lfD_r)(g)| \, , 

    \end{align*}

    where $D_l, D_r$ are left- resp. right-invariant differential operators on $G_d$ and $\ell(g)$ is the hyperbolic distance between a fixed basepoint $x_o$ and $g.x_o$. Here, $\Xi$ is a spherical function for $(G_d, K_d)$ known as the \emph{Harish-Chandra $\Xi$-function}, and for real $d$-dimensional hyperbolic space it is given by

    \begin{align}
    \label{EqHarishChandraXiFunction}

    \Xi(g) = \frac{2^{\frac{d-1}{2}}\Gamma(\frac{d}{2})}{\sqrt{\pi} \, \Gamma(\frac{d - 1}{2})} \sinh(\ell(g))^{2 - d}\int_0^{\ell(g)} (\cosh(\ell(g)) - \cosh(s))^{\frac{d-3}{2}} ds \, .

    \end{align}

    Regarding nuclearity, it is known that the subspace $\mathscr{C}^p(G_d, K_d, \mathbb{R})$ of bi-$K_d$-invariant functions is isomorphic to a Gelfand-Shilov space, see for example \cite[Theorem 2]{Anker1991TheSF}, so it is nuclear and this subspace will suffice for our purposes. We mention briefly that nuclearity of the subspace $\mathscr{C}^p(G_d, \mathbb{R})^{K_d}$ of left-$K_d$-invariant functions can be deduced from a Paley-Wiener-type result for the Helgason-Fourier transform due to Helgason for $p = 2$ and Eguchi in \cite[Theorem 4.1.1, p.193]{EguchiHCLpSpaces} for general $0 < p \leq 2$.

\end{enumerate}

\label{TheoremBochnerMinlos}

Let $\mathscr{A}$ be a real nuclear Frech\'et vector space and let $\Lambda: \mathscr{A} \rightarrow \mathbb{C}$ be a positive-definite continuous function such that $\Lambda(0) = 1$. Then there is a unique probability measure $\mu_{\Lambda}$ on the strong dual space $\mathscr{A}'$ such that

\begin{align*}

\Lambda(f) = \int_{\mathscr{A}'} \ensuremath{\mathrm{e}}^{i\xi(f)} d\mu_{\Lambda}(\xi) \, , \quad \forall \, f \in \mathscr{A} \, . 

\end{align*}

Let $\sigma \in \mathscr{M}_+(\mathcal{S}^+)$ and assume that the linear functional 

\begin{align*}

b_{\sigma}(\varphi) = \int_{\mathcal{S}^+} \widehat{\varphi}^{\natural}(\omega) d\sigma(\omega) \, , \quad \varphi \in \mathscr{A}_o(G)

\end{align*}

is continuous. Then there is a unique $G$-invariant Gaussian probability measure $\mu_{\sigma}$ on $\mathscr{A}_o'(X)$ such that 

\begin{align*}

\mathrm{Var}_{\mu_{\sigma}}(\mathbb{S} f) = \int_{\mathcal{S}^+} |\widehat{\varphi}_f(\omega)|^2 d\sigma(\omega) 

\end{align*}

for all $K$-invariant $f \in \mathscr{A}_o(X)$.

We first note that since $\sigma$ is a positive measure on the positive-definite spherical functions, $b_{\sigma}$ defines a positive-definite continuous $\mathscr{A}_o(G)$-distribution on $G$. To see this we apply Fubini, 

\begin{align*}

b_{\sigma}(\check{\varphi} * \varphi) &= \int_{\mathcal{S}^+} \widehat{(\check{\varphi} * \varphi)^{\natural}}(\omega) d\sigma(\omega) \\

&= \int_{K \times K} \int_{\mathcal{S}^+} \Big( \int_G (\check{\varphi} * \varphi)(k_1 g k_2) \omega(g^{-1}) dm_G(g) \Big) d\sigma(\omega) dm_K^{\otimes 2}(k_1, k_2) \\

&= \int_{\mathcal{S}^+} \Big( \int_G (\check{\varphi} * \varphi)(g) \omega(g^{-1}) dm_G(g) \Big) d\sigma(\omega)\geq 0 \, , \quad \forall \, \varphi \in \mathscr{A}_o(G) \, . 

\end{align*}

This allows us to define a positive-definite continuous bilinear form $B_{\sigma}$ on $\mathscr{A}_o(G)$ by $B_{\sigma}(\varphi_1, \varphi_2) = b_{\sigma}(\check{\varphi}_2 * \varphi_1)$. Note that

\begin{align*}

B_{\sigma}(\lambda_G(g)\varphi_1, \lambda_G(g)\varphi_2) = B_{\sigma}(\varphi_1, \varphi_2)

\end{align*}

for all $g \in G$ since 

\begin{align*}

((\lambda_G(g)\varphi_2)^{\vee} * (\lambda_G(g)\varphi_1))(h) &= \int_G \varphi_2(g^{-1}\ell^{-1}) \varphi_2(g^{-1}\ell^{-1}h) dm_G(\ell) \\

&= \int_G \varphi_2(\ell^{-1}) \varphi_2(\ell^{-1}h) dm_G(\ell) = (\check{\varphi}_2 * \varphi_1)

\end{align*}

for all $\varphi_1, \varphi_2 \in \mathscr{A}_o(G)$. With such a bilinear form we define a $\lambda_G$-invariant Gaussian function $\Lambda_{\sigma} : \mathscr{A}_o(G) \rightarrow \mathbb{C}$ by

\begin{align*}

\Lambda_{\sigma}(\varphi) = \ensuremath{\mathrm{e}}^{-\frac{1}{2}B_{\sigma}(\varphi, \varphi)} \, , \quad \varphi \in \mathscr{A}_o(G) \, . 

\end{align*}

One readily checks that $\Lambda_{\sigma}$ is positive-definite, $\Lambda_{\sigma}(0) = 1$, so by the Bochner-Minlos Theorem there is a unique $G$-invariant probability measure $\widetilde{\mu}_{\sigma}$ on $\mathscr{A}_o'(G)$ such that 

\begin{align*}

\ensuremath{\mathrm{e}}^{-\frac{1}{2}B_{\sigma}(\varphi, \varphi)} = \int_{\mathscr{A}_o'(G)} \ensuremath{\mathrm{e}}^{i \zeta(\varphi)} d\widetilde{\mu}_{\sigma}(\zeta) \, , \quad \forall \, \varphi \in \mathscr{A}_o(G) \, . 

\end{align*}

Restricting this equality to functions of the form $\varphi_f(g) = f(g.o)$ for $f \in \mathscr{A}_o(X)$ provides us with a $G$-invariant probability measure $\mu_{\sigma}$ on $\mathscr{A}_o'(X)$ satisfying 

\begin{align*}

\ensuremath{\mathrm{e}}^{-\frac{1}{2}B_{\sigma}(\varphi_f, \varphi_f)} = \int_{\mathscr{A}_o'(X)} \ensuremath{\mathrm{e}}^{i \xi(f)} d\mu_{\sigma}(\xi) \, , \quad f \in \mathscr{A}_o(X) \, .  

\end{align*}

Since this expression remains positive-definite on $\mathscr{A}_o(X)$, the measure $\mu_{\sigma}$ is unique by the Bochner-Minlos Theorem. Note also that since $\mu_{\sigma}$ is Gaussian, it has well-defined moments of all orders. Finally, the map 

\begin{align*}

\mathbb{R} \ni t \longmapsto \ensuremath{\mathrm{e}}^{-\frac{t^2}{2}B_{\sigma}(\varphi_f, \varphi_f)} \in \mathbb{R}_{> 0}

\end{align*}

is $C^2$ for every $f \in \mathscr{A}_o(X)$, so we can compute the $\mu_{\sigma}$-expectation and variance of linear statistics:

\begin{align*}

\mathbb{E}_{\mu_{\sigma}}(\mathbb{S} f) = \int_{\mathscr{A}_o'(X)} \xi(f) d\mu_{\sigma}(\xi) = -i \frac{d}{dt} \ensuremath{\mathrm{e}}^{-\frac{t^2}{2}B_{\sigma}(\varphi_f, \varphi_f)} \Big|_{t = 0} = 0 \, , 

\end{align*}

and 

\begin{align*}

\mathrm{Var}_{\mu_{\sigma}}(\mathbb{S} f) &= \mathbb{E}_{\mu_{\sigma}}((\mathbb{S} f)^2) = \int_{\mathscr{A}_o'(X)} \xi(f)^2 d\mu(\xi) = - \frac{d^2}{dt^2} \ensuremath{\mathrm{e}}^{-\frac{t^2}{2}B_{\sigma}(\varphi_f, \varphi_f)}\Big|_{t = 0} \\

&= B_{\sigma}(\varphi_f, \varphi_f) = \int_{\mathcal{S}^+} \widehat{(\check{\varphi}_f * \varphi_f)}(\omega) d\sigma(\omega) \, . 

\end{align*}

In particular, if $f \in \mathscr{A}_o(X)$ is $K$-invariant, then

\begin{align*}

\mathrm{Var}_{\mu_{\sigma}}(\mathbb{S} f) = \int_{\mathcal{S}^+} |\widehat{\varphi}_f(\omega)|^2 d\sigma(\omega) \, . 

\end{align*}

A translation invariant locally square-integrable random (tempered) distribution is \emph{spectrally hyperuniform} if 

\begin{align*}

\lim_{\varepsilon \rightarrow 0^+} \frac{\sigma_{\mu}(B_{\varepsilon}(0))}{\mathrm{Vol}_{\mathbb{R}^d}(B_{\varepsilon}(0))} = 0 \, . 

\end{align*}

\label{DefHyperbolicSpectralHyperuniformity}

A $G_d$-invariant locally square-integrable random distribution $\mu$ on $\mathbb{H}^d$ is \emph{spectrally hyperuniform} if

\begin{align*}

\sigma_{\mu}(i[0, \tfrac{d-1}{2}]) = 0 \quad \mbox{ and } \quad \lim_{\varepsilon \rightarrow 0^+} \frac{\sigma_{\mu}((0, \varepsilon])}{\sigma_{\mathcal{P}}((0, \varepsilon])} = 0 \, . 

\end{align*}

\label{PropTemperedHyperuniformity}

Let $F : \mathbb{R} \rightarrow \mathbb{R}$ is an even Schwartz function which does not vanish on $[-1, 1]$ and let $\sigma \in \mathscr{M}_+((0, +\infty))$ be a tempered measure. Then 

\begin{align*}

\lim_{\varepsilon \rightarrow 0^+} \frac{\sigma((0, \varepsilon])}{\varepsilon^{\alpha}} = 0

\end{align*}

if and only if

\begin{align*}

\lim_{s \rightarrow +\infty} s^{\alpha} \int_0^{\infty} F(s\lambda)^2 d\sigma(\lambda) = 0 \, . 

\end{align*}

\label{LemmaHeatKernelHyperuniformityConditions}

Suppose that there are constants $\alpha, \beta > 0$, $\gamma \in (0, 1)$, $A, B, C \geq 0$ and Borel functions $ \theta, \psi : [0, +\infty) \rightarrow [0, +\infty)$ satisfying

(i) $\theta$ is increasing and such that 
\begin{itemize}
    \item for every $\varepsilon > 0$ there is an $r_{\varepsilon} \in (0, 1)$ with $r_{\varepsilon} \rightarrow 0$ as $\varepsilon \rightarrow 0^+$, and such that $\theta(r) \leq A \varepsilon r^{\alpha}$ for all $r \in [0, r_{\varepsilon}^{1 - \gamma}]$,
    \item there is a constant $M > 0$ such that $\theta(r) \leq B r^{\beta}$ for all $r \geq M$.
\end{itemize}

(ii) $\psi$ is such that
\begin{enumerate}
    \item $\int_0^{\infty} r^{\alpha} \psi(r) dr < +\infty$,
    \item $R^{\alpha/\gamma} \int_R^{\infty} \psi(r) dr \rightarrow 0$ as $R \rightarrow +\infty$,
    \item $R^{\alpha - \beta} \int_R^{\infty} r^{\beta} \psi(r) dr \rightarrow 0$ as $R \rightarrow +\infty$.
\end{enumerate}

Then

\begin{align*} 

r_{\varepsilon}^{-(\alpha + 1)} \int_0^{\infty} \psi(r/r_{\varepsilon}) \theta(r) dr \longrightarrow 0 \, , \quad \varepsilon \rightarrow 0^+  \, . 

\end{align*}

Let $I(\varepsilon) = \int_0^{\infty} \psi(r/r_{\varepsilon}) \theta(r) dr$ and split the integral as $I(\varepsilon) = I_1(\varepsilon) + I_2(\varepsilon) + I_3(\varepsilon)$, where

\begin{align*}

I_1(\varepsilon) &= \int_0^{r_{\varepsilon}^{1 - \gamma}} \psi(r/r_{\varepsilon}) \theta(r) dr \\

I_2(\varepsilon) &= \int_{r_{\varepsilon}^{1 - \gamma}}^{M} \psi(r/r_{\varepsilon}) \theta(r) dr \\

I_3(\varepsilon) &= \int_M^{\infty} \psi(r/r_{\varepsilon}) \theta(r) dr \, . 

\end{align*}

By the assumptions on $\theta$, we find that 

\begin{align*}

I_1(\varepsilon) &\leq A \varepsilon  \int_0^{r_{\varepsilon}^{1 - \gamma}} r^{\alpha} \psi(r/r_{\varepsilon}) dr \leq A \varepsilon r_{\varepsilon}^{\alpha + 1} \int_0^{\infty} r^{\alpha} \psi(r) dr \, , \\

I_2(\varepsilon) &\leq \theta(M) \int_{r_{\varepsilon}^{1 - \gamma}}^{M} \psi(r/r_{\varepsilon}) dr \leq \theta(M) r_{\varepsilon} \int_{r_{\varepsilon}^{-\gamma}}^{\infty} \psi(r) dr \\

I_3(\varepsilon) &\leq B \int_{M}^{\infty} r^{\beta} \psi(r/r_{\varepsilon}) dr = B r_{\varepsilon}^{\beta + 1} \int_{M r_{\varepsilon}^{-1}}^{\infty} r^{\beta} \psi(r) dr \, . 

\end{align*}

Dividing by $r_{\varepsilon}^{\alpha + 1}$ and using the assumptions made on $\psi$, we get that

\begin{align*}

r_{\varepsilon}^{-(\alpha + 1)}I(\varepsilon) \leq A \varepsilon \int_0^{\infty} r^{\alpha} \psi(r) dr &+ \theta(M) (r_{\varepsilon}^{-\gamma})^{\alpha/\gamma} \int_{r_{\varepsilon}^{-\gamma}}^{\infty} \psi(r) dr \\

&+  B M^{\beta - \alpha} (M r_{\varepsilon}^{-1})^{\alpha - \beta} \int_{M r_{\varepsilon}^{-1}}^{\infty} r^{\beta} \psi(r) dr \longrightarrow 0 

\end{align*}

as $\varepsilon \rightarrow 0^+$.

For the right implication, set $\theta(r) = \sigma((0, r])$ and \\ $\psi(r) = -2F'(r)F(r)$, so that 

\begin{align*}

\int_0^{\infty} |F(s\lambda)|^2 d\sigma(\lambda) &= \int_0^{\infty} \sigma\big(\big\{ \lambda \geq 0 : F(s\lambda)^2 \geq r \big\}\big) dr \\

&= -2 s \int_0^{\infty} F'(sr)F(sr) \sigma((0, r]) dr = s \int_0^{\infty} \psi(sr) \theta(r) dr \, . 

\end{align*}

Now, since $\sigma$ is tempered and satisfies $\sigma((0, \varepsilon]) = o(\varepsilon^{\alpha})$, then $\theta$ satisfies the two first conditions in Lemma \ref{LemmaHeatKernelHyperuniformityConditions} with $r_{\varepsilon} = s^{-1}$. Moreover, since $F$ is Schwartz, then $\psi = -2 F' F$ is Schwartz and thus $|\psi|$ satisfies the three latter conditions in Lemma \ref{LemmaHeatKernelHyperuniformityConditions}, so we get that

\begin{align*}

s^{\alpha} \int_0^{\infty} F(s\lambda)^2 d\sigma(\lambda) \leq (s^{-1})^{-(\alpha + 1)} \int_0^{\infty} |\psi(r/s^{-1})| \theta(r) dr \rightarrow 0 \, , \quad s \rightarrow +\infty

\end{align*}

as desired. 

Conversely, consider the lower bound

\begin{align*}

s^{\alpha} \int_0^{\infty} F(s\lambda)^2 d\sigma(\lambda) \geq s^{\alpha} \int_0^{1/s} F(s\lambda)^2 d\sigma(\lambda) \geq \sup_{t \in [0, 1]} F(t)^2 s^{\alpha} \sigma([0, s^{-1}]) \, . 

\end{align*}

If 

\begin{align*}

\lim_{s \rightarrow +\infty} s^{\alpha} \int_0^{\infty} F(s\lambda)^2 d\sigma(\lambda) = 0

\end{align*}

then setting $\varepsilon = s^{-1}$ yields

\begin{align*}

\limsup_{\varepsilon \rightarrow 0^+} \frac{\sigma((0, \varepsilon])}{\varepsilon^{\alpha}} \leq \frac{1}{\sup_{t \in [0, 1]} F(t)^2} \lim_{\varepsilon \rightarrow 0} \varepsilon^{-\alpha} \int_0^{\infty} F(\lambda/\varepsilon)^2 d\sigma(\lambda)  = 0 \, . 

\end{align*}

\label{ThmEuclideanHeatKernelHyperuniformity}

An invariant locally square-integrable random tempered distribution $\mu$ on $\mathbb{R}^d$ is spectrally hyperuniform if and only if 

\begin{align*} 


\lim_{\tau \rightarrow +\infty} \, \tau^{d/2} \mathrm{Var}_{\mu}(\mathbb{S} h_{\tau}) = 0 \, .   

\end{align*}

Since the heat kernel $h_{\tau}$ is radial, the variance of its linear statistic with respect to $\mu$ can be written in terms of the radialized Bartlett spectral measure $\sigma_{\mu}^{\mathrm{rad}}$ as 

\begin{align*}

\tau^{d/2} \mathrm{Var}_{\mu}(\mathbb{S} h_{\tau}) =  \tau^{d/2}  \int_0^{\infty} \widehat{h}_{\tau}(\lambda)^2 d\sigma_{\mu}^{\mathrm{rad}}(\lambda) = \tau^{d/2}  \int_0^{\infty} \ensuremath{\mathrm{e}}^{-2\tau \lambda^2} d\sigma_{\mu}^{\mathrm{rad}}(\lambda) \, . 

\end{align*}

As mentioned, the measure $\sigma_{\mu}$ is tempered as a consequence of the Paley-Wiener Theorem, so letting $s = \sqrt{\tau}$, $\alpha = d$, $F(t) = \ensuremath{\mathrm{e}}^{-t^2}$, then by Proposition \ref{PropTemperedHyperuniformity} we have that

\begin{align*}

\lim_{\tau \rightarrow +\infty} \tau^{d/2} \mathrm{Var}_{\mu}(\mathbb{S} h_{\tau}) = \lim_{s \rightarrow +\infty} s^{\alpha} \int_0^{\infty} F(s\lambda)^2 d\sigma_{\mu}^{\mathrm{rad}}(\lambda) = 0

\end{align*}

if and only if $\sigma_{\mu}^{\mathrm{rad}}((0, \varepsilon]) = o(\varepsilon^{d})$ as $\varepsilon \rightarrow 0^+$.

\label{ThmHyperbolicHeatKernelHyperuniformity}

An invariant locally square-integrable random Harish-Chandra distribution $\mu$ on $\mathbb{H}^d$ is spectrally hyperuniform if and only if 

\begin{align*} 

\lim_{\tau \rightarrow +\infty} \, \tau^{3/2} \ensuremath{\mathrm{e}}^{\frac{(d-1)^2}{2} \tau} \,  \mathrm{Var}_{\mu}(\mathbb{S} h_{\tau}) = 0 \, .   

\end{align*}

The proof is similar to the Euclidean case in Theorem \ref{ThmEuclideanHeatKernelHyperuniformity}. In terms of the Bartlett spectral measure, the heat kernel variance with respect to $\mu$ can be written as 

\begin{equation}
\begin{split}
\label{EqHyperbolicHeatKernelHyperuniformityIdenitity}

 \tau^{3/2} \ensuremath{\mathrm{e}}^{\frac{(d-1)^2}{2} \tau} \,  \mathrm{Var}_{\mu}(\mathbb{S} h_{\tau}) &= \tau^{3/2}  \ensuremath{\mathrm{e}}^{\frac{(d-1)^2}{2} \tau} \Big( \int_0^{\infty} \widehat{h}_{\tau}(\lambda)^2 d\sigma_{\mu}^{(p)}(\lambda) +  \int_0^{\frac{d-1}{2}} \widehat{h}_{\tau}(i\lambda)^2 d\sigma_{\mu}^{(c)}(\lambda) \Big)\\

&=   \tau^{3/2}  \int_0^{\infty} \ensuremath{\mathrm{e}}^{-2\tau\lambda^2} d\sigma_{\mu}^{(p)}(\lambda) +  \tau^{3/2}  \int_0^{\frac{d-1}{2}} \ensuremath{\mathrm{e}}^{2\tau\lambda^2} d\sigma_{\mu}^{(c)}(\lambda) \, , 

\end{split}
\end{equation}

where $\sigma_{\mu}^{(p)}$ and $\sigma_{\mu}^{(c)}$ are the restrictions of $\sigma_{\mu}$ to $(0, +\infty)$ and $i[0, \tfrac{d-1}{2}]$ respectively.

First, assume that $\mu$ is spectrally hyperuniform, in other words that $\sigma_{\mu}^{(c)} = 0$ and $\sigma_{\mu}^{(p)}((0, \varepsilon]) = o(\varepsilon^3)$ as $\varepsilon \rightarrow 0^+$. Since $\sigma_{\mu}$ is positive and tempered and 

$$\widehat{h}_{\tau}(\lambda) = \ensuremath{\mathrm{e}}^{-\tau(\frac{(d-1)^2}{4} + \lambda^2)}$$

is a positive decaying Schwartz function, Proposition \ref{PropTemperedHyperuniformity} yields

\begin{align*}

\lim_{\tau \rightarrow +\infty} \, \tau^{3/2} \ensuremath{\mathrm{e}}^{\frac{(d-1)^2}{2} \tau} \,  \mathrm{Var}_{\mu}(\mathbb{S} h_{\tau}) = \lim_{s \rightarrow +\infty} s^3  \int_0^{\infty} \ensuremath{\mathrm{e}}^{-2 (s\lambda)^2} d\sigma_{\mu}^{(p)}(\lambda) = 0 \, . 

\end{align*}

Conversely, suppose that 

$$\tau^{3/2} \ensuremath{\mathrm{e}}^{\frac{(n-1)^2}{2} \tau} \mathrm{Var}_{\mu}(\mathbb{S} h_{\tau}) \rightarrow 0 $$

as $\tau \rightarrow +\infty$. Then it is clear from Equation \eqref{EqHyperbolicHeatKernelHyperuniformityIdenitity} that we must have $\sigma_{\mu}^{(c)} = 0$, and so 

\begin{align*}

\lim_{s \rightarrow +\infty} s^3  \int_0^{\infty} \ensuremath{\mathrm{e}}^{-2 (s\lambda)^2} d\sigma_{\mu}^{(p)}(\lambda) = 0 \, . 

\end{align*}

Since $\sigma_{\mu}^{(p)}$ is a tempered measure on $(0, +\infty)$, Proposition \ref{PropTemperedHyperuniformity} implies that

\begin{align*}

\frac{\sigma_{\mu}^{(p)}((0, \varepsilon])}{\varepsilon^3} \longrightarrow 0 \, , \quad \varepsilon \rightarrow 0^+ \, ,

\end{align*}

so $\mu$ is spectrally hyperuniform.
